#include <bits/stdc++.h>
using namespace std;
int main(){
    int m; cin>>m;
    for(int c=0;c<m;c++){
        int n,k; cin>>n>>k;
        vector<char> reach(k,0), nreach(k,0);
        reach[0]=1;
        for(int i=0;i<n;i++){
            long long a; cin>>a;
            int am = ((a % k) + k) % k;
            fill(nreach.begin(), nreach.end(), 0);
            for(int r=0;r<k;r++) if(reach[r]){
                nreach[(r+am)%k]=1;
                nreach[((r-am)%k+k)%k]=1;
            }
            reach = nreach;
        }
        cout << (reach[0] ? "Divisible" : "Not divisible") << "\n";
    }
}

